-- Inventory values are transcribed from the supplied workbooks, never interpreted as medical advice.
insert into public.role_module_permissions(role_key,module_key,is_visible)
select key,'pharmacy',true from public.roles where key in ('admin','direction','armement','capitaine','marin')
on conflict(role_key,module_key) do nothing;

create schema pharmacy_private;
revoke all on schema pharmacy_private from public,anon,authenticated;
grant usage on schema pharmacy_private to authenticated;
alter default privileges in schema pharmacy_private revoke execute on functions from public;

create function pharmacy_private.can_access(p_company_id bigint,p_vessel_id bigint)
returns boolean language sql stable security definer set search_path='' as $$
  select auth.uid() is not null and public.user_belongs_to_company(p_company_id)
    and exists(select 1 from public.vessels v where v.id=p_vessel_id and v.company_id=p_company_id
      and v.active and v.asset_kind='vessel')
    and exists(select 1 from public.user_roles r join public.role_module_permissions p on p.role_key=r.role_key
      where r.user_id=auth.uid() and r.company_id=p_company_id and p.module_key='pharmacy' and p.is_visible
        and r.role_key in ('admin','direction','armement','capitaine','marin'))
    and (public.has_company_role(p_company_id,array['admin','direction','armement'])
      or coalesce(public.planning_can_read_row(p_company_id,p_vessel_id,null,
        (current_timestamp at time zone 'Europe/Paris')::date,(current_timestamp at time zone 'Europe/Paris')::date),false));
$$;
create function pharmacy_private.can_manage(p_company_id bigint,p_vessel_id bigint)
returns boolean language sql stable security invoker set search_path='' as $$
  select pharmacy_private.can_access(p_company_id,p_vessel_id)
    and public.has_company_role(p_company_id,array['admin','direction','armement','capitaine']);
$$;
revoke all on function pharmacy_private.can_access(bigint,bigint),pharmacy_private.can_manage(bigint,bigint) from public,anon;
grant execute on function pharmacy_private.can_access(bigint,bigint),pharmacy_private.can_manage(bigint,bigint) to authenticated;

create table public.pharmacy_inventory (
  id bigint generated always as identity primary key,
  company_id bigint not null references public.companies(id),
  vessel_id bigint not null references public.vessels(id),
  section text not null default '' check(length(section)<=500),
  category text not null default '' check(length(category)<=500),
  brand text not null default '' check(length(brand)<=500),
  designation text not null check(length(btrim(designation)) between 1 and 2000),
  lot_number text not null default '' check(length(lot_number)<=500),
  quantity text not null default '' check(length(quantity)<=250),
  required_quantity text not null default '' check(length(required_quantity)<=250),
  expires_on date,
  expiry_text text not null default '' check(length(expiry_text)<=500),
  expiry_precision text not null default 'unknown' check(expiry_precision in ('day','month','unknown')),
  notes text not null default '' check(length(notes)<=6000),
  active boolean not null default true,
  revision integer not null default 1 check(revision>=1),
  source_file text not null default 'SeaPilot', source_sheet text not null default '', source_row integer,
  source_data jsonb not null default '{}'::jsonb,
  created_by uuid references auth.users(id), updated_by uuid references auth.users(id),
  created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(),
  unique(company_id,vessel_id,source_file,source_sheet,source_row),
  check((expires_on is null and expiry_precision='unknown') or (expires_on is not null and expiry_precision in ('day','month')))
);
create index pharmacy_inventory_vessel_idx on public.pharmacy_inventory(vessel_id,active,expires_on);
create index pharmacy_inventory_company_idx on public.pharmacy_inventory(company_id);
create index pharmacy_inventory_created_by_idx on public.pharmacy_inventory(created_by);
create index pharmacy_inventory_updated_by_idx on public.pharmacy_inventory(updated_by);

create table public.pharmacy_controls (
  id bigint generated always as identity primary key,
  company_id bigint not null references public.companies(id), vessel_id bigint not null references public.vessels(id),
  issued_on date, expires_on date not null, storage_path text not null unique,
  file_name text not null check(length(btrim(file_name)) between 1 and 500),
  file_size bigint not null check(file_size between 1 and 20971520),
  mime_type text not null check(mime_type in ('application/pdf','image/jpeg','image/png')),
  is_current boolean not null default true, revision integer not null check(revision>=1),
  created_by uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(),
  check(issued_on is null or issued_on<=expires_on)
);
create unique index pharmacy_controls_current_idx on public.pharmacy_controls(vessel_id) where is_current;
create index pharmacy_controls_scope_idx on public.pharmacy_controls(company_id,vessel_id);
create index pharmacy_controls_created_by_idx on public.pharmacy_controls(created_by);
alter table public.pharmacy_inventory enable row level security;
alter table public.pharmacy_controls enable row level security;
revoke all on public.pharmacy_inventory,public.pharmacy_controls from public,anon,authenticated;
grant select on public.pharmacy_inventory,public.pharmacy_controls to authenticated;
create policy pharmacy_inventory_read on public.pharmacy_inventory for select to authenticated
  using(pharmacy_private.can_access(company_id,vessel_id));
create policy pharmacy_controls_read on public.pharmacy_controls for select to authenticated
  using(pharmacy_private.can_access(company_id,vessel_id));

create function pharmacy_private.available_vessels()
returns table(id bigint,company_id bigint,name text,acronym text,can_manage boolean)
language sql stable security definer set search_path='' as $$
  select v.id,v.company_id,v.name,v.acronym,pharmacy_private.can_manage(v.company_id,v.id)
  from public.vessels v where pharmacy_private.can_access(v.company_id,v.id) order by v.name,v.id;
$$;
create function public.pharmacy_available_vessels()
returns table(id bigint,company_id bigint,name text,acronym text,can_manage boolean)
language sql stable security invoker set search_path='' as $$ select * from pharmacy_private.available_vessels(); $$;

create function pharmacy_private.save_item(p_vessel_id bigint,p_item jsonb,p_id bigint,p_revision integer)
returns bigint language plpgsql security definer set search_path='' as $$
declare c bigint:=public.current_planning_company_id(); result_id bigint; r public.pharmacy_inventory%rowtype;
begin
  if not coalesce(pharmacy_private.can_manage(c,p_vessel_id),false) then
    raise exception using errcode='42501',message='Accès refusé à la modification de cet inventaire.'; end if;
  if p_item is null or jsonb_typeof(p_item)<>'object' or octet_length(p_item::text)>20000 then
    raise exception 'Contenu de l’article invalide.'; end if;
  if p_id is null then
    insert into public.pharmacy_inventory(company_id,vessel_id,section,category,brand,designation,lot_number,quantity,required_quantity,expires_on,expiry_text,expiry_precision,notes,active,created_by,updated_by)
    values(c,p_vessel_id,coalesce(p_item->>'section',''),coalesce(p_item->>'category',''),coalesce(p_item->>'brand',''),btrim(p_item->>'designation'),coalesce(p_item->>'lot_number',''),
      coalesce(p_item->>'quantity',''),coalesce(p_item->>'required_quantity',''),nullif(p_item->>'expires_on','')::date,
      coalesce(p_item->>'expiry_text',''),coalesce(p_item->>'expiry_precision','unknown'),coalesce(p_item->>'notes',''),coalesce((p_item->>'active')::boolean,true),auth.uid(),auth.uid())
    returning id into result_id;
  else
    select * into r from public.pharmacy_inventory where id=p_id and company_id=c and vessel_id=p_vessel_id for update;
    if r.id is null then raise exception using errcode='42501',message='Article introuvable ou accès refusé.'; end if;
    if p_revision is distinct from r.revision then raise exception using errcode='40001',message='Cet article a été modifié sur un autre appareil. Rechargez l’inventaire.'; end if;
    update public.pharmacy_inventory set section=coalesce(p_item->>'section',''),category=coalesce(p_item->>'category',''),brand=coalesce(p_item->>'brand',''),designation=btrim(p_item->>'designation'),
      lot_number=coalesce(p_item->>'lot_number',''),quantity=coalesce(p_item->>'quantity',''),required_quantity=coalesce(p_item->>'required_quantity',''),expires_on=nullif(p_item->>'expires_on','')::date,
      expiry_text=coalesce(p_item->>'expiry_text',''),expiry_precision=coalesce(p_item->>'expiry_precision','unknown'),notes=coalesce(p_item->>'notes',''),active=coalesce((p_item->>'active')::boolean,true),
      revision=revision+1,updated_at=clock_timestamp(),updated_by=auth.uid() where id=r.id returning id into result_id;
  end if;
  return result_id;
end $$;
create function public.save_pharmacy_item(p_vessel_id bigint,p_item jsonb,p_id bigint default null,p_revision integer default null)
returns bigint language sql security invoker set search_path='' as $$ select pharmacy_private.save_item(p_vessel_id,p_item,p_id,p_revision); $$;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('pharmacy-controls','pharmacy-controls',false,20971520,array['application/pdf','image/jpeg','image/png']);
create function pharmacy_private.storage_access(p_path text,p_manage boolean)
returns boolean language plpgsql stable security invoker set search_path='' as $$
declare c bigint; v bigint;
begin
  if p_path !~ '^[0-9]{1,18}/[0-9]{1,18}/[a-f0-9-]{36}\.(pdf|png|jpg)$' then return false; end if;
  c:=split_part(p_path,'/',1)::bigint; v:=split_part(p_path,'/',2)::bigint;
  return case when p_manage then pharmacy_private.can_manage(c,v) else pharmacy_private.can_access(c,v) end;
end $$;
create policy pharmacy_control_upload on storage.objects for insert to authenticated
  with check(bucket_id='pharmacy-controls' and pharmacy_private.storage_access(name,true));
create policy pharmacy_control_download on storage.objects for select to authenticated
  using(bucket_id='pharmacy-controls' and pharmacy_private.storage_access(name,false));

create function pharmacy_private.publish_control(p_vessel_id bigint,p_expected_control_id bigint,p_storage_path text,p_file_name text,p_file_size bigint,p_mime_type text,p_expires_on date,p_issued_on date)
returns bigint language plpgsql security definer set search_path='' as $$
declare c bigint:=public.current_planning_company_id(); r public.pharmacy_controls%rowtype; result_id bigint; next_revision integer;
begin
  if not coalesce(pharmacy_private.can_manage(c,p_vessel_id),false) then
    raise exception using errcode='42501',message='Accès refusé au contrôle pharmacie de ce navire.'; end if;
  -- Serialize two simultaneous replacements, including when no previous control exists.
  perform 1 from public.vessels where id=p_vessel_id and company_id=c for update;
  select * into r from public.pharmacy_controls where vessel_id=p_vessel_id and is_current;
  if r.storage_path=p_storage_path then return r.id; end if;
  if r.id is distinct from p_expected_control_id then raise exception using errcode='40001',message='Le contrôle a été remplacé sur un autre appareil. Rechargez l’inventaire.'; end if;
  if p_expires_on is null or (p_issued_on is not null and p_issued_on>p_expires_on) then raise exception 'Dates du contrôle invalides.'; end if;
  if not pharmacy_private.storage_access(p_storage_path,true) or split_part(p_storage_path,'/',2)<>p_vessel_id::text
    or p_file_size is null or p_file_size not between 1 and 20971520
    or p_mime_type not in ('application/pdf','image/jpeg','image/png')
    or not exists(select 1 from storage.objects where bucket_id='pharmacy-controls' and name=p_storage_path
      and owner_id=auth.uid()::text and metadata->>'mimetype'=p_mime_type and (metadata->>'size')::bigint=p_file_size)
  then raise exception 'Le document doit être déposé dans le stockage privé de ce navire.'; end if;
  next_revision:=coalesce(r.revision,0)+1;
  update public.pharmacy_controls set is_current=false where vessel_id=p_vessel_id and is_current;
  insert into public.pharmacy_controls(company_id,vessel_id,issued_on,expires_on,storage_path,file_name,file_size,mime_type,revision,created_by)
    values(c,p_vessel_id,p_issued_on,p_expires_on,p_storage_path,p_file_name,p_file_size,p_mime_type,next_revision,auth.uid()) returning id into result_id;
  return result_id;
end $$;
create function public.publish_pharmacy_control(p_vessel_id bigint,p_expected_control_id bigint,p_storage_path text,p_file_name text,p_file_size bigint,p_mime_type text,p_expires_on date,p_issued_on date default null)
returns bigint language sql security invoker set search_path='' as $$
  select pharmacy_private.publish_control(p_vessel_id,p_expected_control_id,p_storage_path,p_file_name,p_file_size,p_mime_type,p_expires_on,p_issued_on);
$$;

create function public.pharmacy_notifications()
returns table(id text,kind text,vessel_id bigint,vessel_name text,title text,expires_on date,days_until_expiry integer,item_id bigint)
language sql stable security invoker set search_path='' as $$
  with today as (select (current_timestamp at time zone 'Europe/Paris')::date d)
  select 'control-'||c.id as id,'control' as kind,c.vessel_id,v.name as vessel_name,'Contrôle Pharmacie' as title,c.expires_on,c.expires_on-t.d as days_until_expiry,null::bigint as item_id
    from public.pharmacy_controls c join public.vessels v on v.id=c.vessel_id cross join today t
    where c.is_current and c.expires_on<=t.d+30
  union all
  select 'item-'||i.id,'item',i.vessel_id,v.name,i.designation,i.expires_on,i.expires_on-t.d,i.id
    from public.pharmacy_inventory i join public.vessels v on v.id=i.vessel_id cross join today t
    where i.active and i.expires_on<=t.d+30
  order by expires_on,vessel_name,title;
$$;

revoke all on function pharmacy_private.available_vessels(),pharmacy_private.save_item(bigint,jsonb,bigint,integer),pharmacy_private.storage_access(text,boolean),
  pharmacy_private.publish_control(bigint,bigint,text,text,bigint,text,date,date) from public,anon;
grant execute on function pharmacy_private.available_vessels(),pharmacy_private.save_item(bigint,jsonb,bigint,integer),pharmacy_private.storage_access(text,boolean),
  pharmacy_private.publish_control(bigint,bigint,text,text,bigint,text,date,date) to authenticated;
revoke all on function public.pharmacy_available_vessels(),public.save_pharmacy_item(bigint,jsonb,bigint,integer),
  public.publish_pharmacy_control(bigint,bigint,text,text,bigint,text,date,date),public.pharmacy_notifications() from public,anon;
grant execute on function public.pharmacy_available_vessels(),public.save_pharmacy_item(bigint,jsonb,bigint,integer),
  public.publish_pharmacy_control(bigint,bigint,text,text,bigint,text,date,date),public.pharmacy_notifications() to authenticated;

