  source_vessel jsonb; source_item jsonb; c bigint; v bigint; matching integer;
begin
  select id into c from public.companies where code='bbtm';
  if c is null then raise exception 'La société BBTM est requise pour importer les inventaires pharmacie.'; end if;
  for source_vessel in select value from jsonb_array_elements(sources) loop
    select count(*),min(id) into matching,v from public.vessels
      where company_id=c and active and asset_kind='vessel' and acronym=source_vessel->>'acronym';
    if matching<>1 then raise exception 'Navire actif unique introuvable pour %.',source_vessel->>'vessel'; end if;
    for source_item in select value from jsonb_array_elements(source_vessel->'items') loop
      insert into public.pharmacy_inventory(company_id,vessel_id,section,category,brand,designation,lot_number,quantity,required_quantity,expires_on,expiry_text,expiry_precision,notes,source_file,source_sheet,source_row,source_data)
      values(c,v,source_item->>'section',source_item->>'category',source_item->>'brand',source_item->>'designation',source_item->>'lot_number',source_item->>'quantity',source_item->>'required_quantity',
        (source_item->>'expires_on')::date,source_item->>'expiry_text',source_item->>'expiry_precision',source_item->>'notes',source_item->>'source_file',source_item->>'source_sheet',(source_item->>'source_row')::integer,source_item->'source_data')
      on conflict(company_id,vessel_id,source_file,source_sheet,source_row) do nothing;
    end loop;
    if (select count(*) from public.pharmacy_inventory where vessel_id=v and source_file=(source_vessel->'items'->0->>'source_file')) <> jsonb_array_length(source_vessel->'items') then
      raise exception 'Le nombre d’articles importés ne correspond pas au classeur de %.',source_vessel->>'vessel'; end if;
  end loop;
end $seed$;
